import React from "react"
import "./bold-button.scss"

class BoldPaymentButton extends React.Component {
  constructor(props) {
    super(props)
    this.containerRef = React.createRef()
  }

  componentDidMount() {
    if (typeof window !== "undefined") {
      const script = document.createElement("script")
      script.src = "https://checkout.bold.co/library/boldPaymentButton.js"
      script.setAttribute("data-bold-button", this.props.variant || "dark-M")
      script.setAttribute("data-api-key", this.props.apiKey)
      script.setAttribute("data-description", this.props.description || "Pago Medsys")

      if (this.props.redirectionUrl) {
        script.setAttribute("data-redirection-url", this.props.redirectionUrl)
      }

      if (this.containerRef.current) {
        this.containerRef.current.appendChild(script)
      }
    }
  }

  componentWillUnmount() {
    if (this.containerRef.current) {
      this.containerRef.current.innerHTML = ""
    }
  }

  render() {
    return (
      <div
        ref={this.containerRef}
        className={`bold-button-container ${this.props.className || ""}`}
      />
    )
  }
}

export default BoldPaymentButton
